  async function addToCart(userId, productVariantCombinationId, quantity = 1) {
    try {
      if (!userId) {
        console.error('addToCart: userId is required');
        return null;
      }

      // 1. Get or create cart for user
      let {
        data: cart,
        error: cartError
      } = await supabase.from('carts').select('id').eq('user_id', userId).maybeSingle();
      if (cartError) {
        console.error('Error fetching cart in addToCart:', cartError.message);
      }
      if (!cart) {
        const {
          data: newCart,
          error: newCartError
        } = await supabase.from('carts').insert({
          user_id: userId
        }).select('id').single();
        if (newCartError) {
          console.error('Error creating cart:', newCartError.message);
          return null;
        }
        cart = newCart;
      }

      // 2. Resolve valid product_variant_combination_id
      let validCombinationId = productVariantCombinationId;

      // Check if ID exists in product_variant_combinations
      const {
        data: existingPvc
      } = await supabase.from('product_variant_combinations').select('id, product_id, price').eq('id', productVariantCombinationId).maybeSingle();
      if (existingPvc) {
        validCombinationId = existingPvc.id;
      } else {
        // productVariantCombinationId might be a product_id
        // Check if a combination exists for this product_id
        const {
          data: comboForProduct
        } = await supabase.from('product_variant_combinations').select('id, product_id, price').eq('product_id', productVariantCombinationId).limit(1).maybeSingle();
        if (comboForProduct) {
          validCombinationId = comboForProduct.id;
        } else {
          // Find product to create default combination so foreign key is valid
          const {
            data: prod
          } = await supabase.from('products').select('id, amount, product_name').eq('id', productVariantCombinationId).maybeSingle();
          if (prod) {
            const {
              data: createdCombo,
              error: createComboError
            } = await supabase.from('product_variant_combinations').insert({
              product_id: prod.id,
              combination_string: 'Default',
              price: prod.amount || 0,
              quantity: 100,
              sku: ''
            }).select('id').single();
            if (createdCombo) {
              validCombinationId = createdCombo.id;
            } else {
              console.error('Failed to create default combination:', createComboError?.message);
            }
          }
        }
      }
      if (!validCombinationId) {
        console.error('addToCart: Unable to resolve valid combination ID for:', productVariantCombinationId);
        return null;
      }

      // 3. Check if cart item already exists
      const {
        data: existingItem
      } = await supabase.from('cart_items').select('id, quantity').eq('cart_id', cart.id).eq('product_variant_combination_id', validCombinationId).maybeSingle();
      if (existingItem) {
        const {
          data,
          error
        } = await supabase.from('cart_items').update({
          quantity: existingItem.quantity + quantity
        }).eq('id', existingItem.id).select();
        if (error) {
          console.error('Error updating existing cart item:', error.message);
          return null;
        }
        return data ? data[0] : null;
      }

      // 4. Insert new cart item
      const {
        data,
        error
      } = await supabase.from('cart_items').insert({
        cart_id: cart.id,
        product_variant_combination_id: validCombinationId,
        quantity: quantity
      }).select();
      if (error) {
        console.error('Error adding to cart:', error.message);
        return null;
      }
      return data ? data[0] : null;
    } catch (err) {
      console.error('Unexpected error in addToCart:', err);
      return null;
    }
  }
