  // Order Management Functions
  async function getOrders(userId, options = {}) {
    console.log('getOrders: userId', userId, 'options', options);
    if (!userId) return [];
    const isSeller = options.role === 'seller' || options.isSeller;
    const isAdmin = options.role === 'admin' || options.role === 'superadmin';
    const selectQuery = `
    *,
    order_items (
      id,
      quantity,
      price,
      product_variant_combination_id,
      product_variant_combinations (
        id,
        combination_string,
        price,
        products (
          id,
          product_name,
          user_id,
          customer_id,
          product_media (media_url, media_type)
        )
      )
    )
  `;
    let orders = [];
    if (isSeller) {
      // 1. Try querying orders where seller_id = userId OR user_id = userId (for shop orders created by seller)
      try {
        const {
          data: sellerData,
          error: sellerErr
        } = await supabase.from('orders').select(selectQuery).or(`seller_id.eq.${userId},user_id.eq.${userId}`).order('created_at', {
          ascending: false
        });
        if (!sellerErr && Array.isArray(sellerData)) {
          orders = sellerData;
        } else if (sellerErr) {
          console.warn('getOrders: seller_id query notice:', sellerErr.message);
        }
      } catch (err) {
        console.warn('getOrders: seller_id query exception:', err);
      }

      // 2. Product-linked fallback for older legacy orders created prior to seller_id column
      // Only query if direct seller_id match found nothing, ensuring instantaneous load times
      if (orders.length === 0) {
        try {
          const {
            data: myProducts
          } = await supabase.from('products').select('id').or(`user_id.eq.${userId},customer_id.eq.${userId}`);
          if (myProducts && myProducts.length > 0) {
            const prodIds = myProducts.map(p => p.id);
            const {
              data: combinations
            } = await supabase.from('product_variant_combinations').select('id').in('product_id', prodIds);
            if (combinations && combinations.length > 0) {
              const combiIds = combinations.map(c => c.id);
              const {
                data: items
              } = await supabase.from('order_items').select('order_id').in('product_variant_combination_id', combiIds);
              if (items && items.length > 0) {
                const linkedOrderIds = Array.from(new Set(items.map(it => it.order_id).filter(Boolean)));
                if (linkedOrderIds.length > 0) {
                  const existingIds = new Set(orders.map(o => o.id));
                  const missingIds = linkedOrderIds.filter(id => !existingIds.has(id));
                  if (missingIds.length > 0) {
                    const {
                      data: extraOrders
                    } = await supabase.from('orders').select(selectQuery).in('id', missingIds).order('created_at', {
                      ascending: false
                    });
                    if (extraOrders && extraOrders.length > 0) {
                      orders = [...orders, ...extraOrders].sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
                    }
                  }
                }
              }
            }
          }
        } catch (fallbackErr) {
          console.warn('getOrders fallback product search notice:', fallbackErr);
        }
      }
    } else if (isAdmin && !options.buyerOnly) {
      const {
        data: adminData,
        error: adminErr
      } = await supabase.from('orders').select(selectQuery).order('created_at', {
        ascending: false
      });
      if (!adminErr && adminData) {
        orders = adminData;
      }
    } else {
      // Buyer query: strictly orders placed by this buyer
      const {
        data: buyerData,
        error: buyerErr
      } = await supabase.from('orders').select(selectQuery).eq('user_id', userId).order('created_at', {
        ascending: false
      });
      if (buyerErr) {
        console.error('getOrders: Error fetching buyer orders:', buyerErr.message);
        return null;
      }
      orders = buyerData || [];
    }

    // Enrich orders with buyer profiles if missing customer names
    try {
      const missingProfileUserIds = Array.from(new Set(orders.filter(o => o.user_id && !o.customer_name).map(o => o.user_id)));
      if (missingProfileUserIds.length > 0) {
        const {
          data: profiles
        } = await supabase.from('profiles').select('id, full_name, mobile').in('id', missingProfileUserIds);
        if (profiles && profiles.length > 0) {
          const profMap = new Map(profiles.map(p => [p.id, p]));
          orders.forEach(ord => {
            if (ord.user_id && profMap.has(ord.user_id)) {
              const p = profMap.get(ord.user_id);
              if (!ord.customer_name && p.full_name) ord.customer_name = p.full_name;
              if (!ord.customer_mobile && p.mobile) ord.customer_mobile = p.mobile;
            }
          });
        }
      }
    } catch (profErr) {
      console.warn('getOrders profile enrichment notice:', profErr);
    }
    return orders;
  }
  async function getOrderById(orderId) {
    try {
      const {
        data,
        error
      } = await supabase.from('orders').select(`
        *,
        order_items (
          id,
          quantity,
          price,
          product_variant_combination_id,
          product_variant_combinations (
            id,
            combination_string,
            price,
            products (
              id,
              product_name,
              user_id,
              customer_id,
              product_media (media_url, media_type)
            )
          )
        )
      `).eq('id', orderId).maybeSingle();
      if (error) {
        console.error('Error fetching order by ID:', error.message);
        return null;
      }
      if (!data) return null;

      // Fetch buyer profile if user_id is set
      if (data.user_id) {
        try {
          const {
            data: userProf
          } = await supabase.from('profiles').select('id, full_name, mobile, email').eq('id', data.user_id).maybeSingle();
          if (userProf) {
            data.customer_profile = userProf;
            if (!data.customer_name && userProf.full_name) data.customer_name = userProf.full_name;
            if (!data.customer_mobile && userProf.mobile) data.customer_mobile = userProf.mobile;
          }
        } catch (_) {}
      }

      // Fetch delivery manager profile if assigned
      if (data.delivery_manager_id) {
        try {
          const {
            data: dmProf
          } = await supabase.from('profiles').select('id, full_name, mobile').eq('id', data.delivery_manager_id).maybeSingle();
          if (dmProf) {
            data.delivery_manager_profile = dmProf;
          }
        } catch (_) {}
      }
      return data;
    } catch (err) {
      console.error('getOrderById exception:', err);
      return null;
    }
  }
