  async function updateOrderPaymentStatus(orderId, paymentStatus) {
    try {
      let {
        data,
        error
      } = await supabase.from('orders').update({
        payment_status: paymentStatus
      }).eq('id', orderId).select();
      if (error && (error.code === 'PGRST204' || error.message?.includes('payment_status'))) {
        // payment_status column not yet in orders table, fallback to shipping_address JSON
        const {
          data: currentOrder
        } = await supabase.from('orders').select('shipping_address').eq('id', orderId).single();
        const currentShipping = typeof currentOrder?.shipping_address === 'object' && currentOrder?.shipping_address !== null ? currentOrder.shipping_address : {
          address: currentOrder?.shipping_address
        };
        const updatedShipping = Object.assign({}, currentShipping, {
          payment_status: paymentStatus
        });
        const res = await supabase.from('orders').update({
          shipping_address: updatedShipping
        }).eq('id', orderId).select();
        return res.data ? res.data[0] : null;
      }
      if (error) {
        console.error('Error updating order payment status:', error.message);
        return null;
      }
      return data ? data[0] : null;
    } catch (err) {
      console.error('updateOrderPaymentStatus exception:', err);
      return null;
    }
  }
